import hourglass.errors


def timesheet_lines(shifts):
    if not shifts:
        raise hourglass.errors.ProjectError("no shifts to report on")

    counts = {}
    minutes = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise hourglass.errors.ProjectError("shift has a blank worker name")
        counts[shift.worker] = counts.get(shift.worker, 0) + 1
        minutes[shift.worker] = minutes.get(shift.worker, 0) + shift.span.minutes

    workers = sorted(minutes, key=lambda name: (-minutes[name], name))
    lines = []
    for name in workers:
        lines.append(f"{name}: {counts[name]} shifts, {minutes[name] / 60:.1f} hours")
    return lines
