cat > qa/test_timesheet.py <<'EOF'
import unittest

import hourglass.errors
import hourglass.models
import hourglass.timesheet


def make_shift(worker, start, end):
    return hourglass.models.Shift(worker, "mon", hourglass.models.Span(start, end))


class TimesheetTest(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("ann", 540, 600),
            make_shift("bob", 540, 720),
            make_shift("ann", 780, 840),
        ]
        self.assertEqual(
            hourglass.timesheet.timesheet_lines(shifts),
            ["bob: 1 shifts, 3.0 hours", "ann: 2 shifts, 2.0 hours"],
        )

    def test_one_decimal(self):
        lines = hourglass.timesheet.timesheet_lines([make_shift("ann", 540, 590)])
        self.assertEqual(lines, ["ann: 1 shifts, 0.8 hours"])

    def test_empty_raises(self):
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.timesheet.timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.timesheet.timesheet_lines([make_shift("  ", 540, 600)])


if __name__ == "__main__":
    unittest.main()
